func memoryStateSeverityRank(code string) int {
	switch code {
	case memoryErrStateUnsafe:
		return 0
	case memoryErrStateCorrupt:
		return 1
	case memoryErrMigrationRequired:
		return 2
	case memoryErrUnsupportedVersion:
		return 3
	default:
		return 4
	}
